      const onUp = () => {
        if(!isDown) return;
        isDown = false;
        track.style.scrollBehavior = '';
      };

      track.addEventListener('mousedown', (e) => {
        if(e.button !== 0) return;
        onDown(e.pageX);
      });
      window.addEventListener('mousemove', (e) => onMove(e.pageX));
      window.addEventListener('mouseup', onUp);

      track.addEventListener('touchstart', (e) => onDown(e.touches[0].pageX), {passive:true});
      track.addEventListener('touchmove', (e) => onMove(e.touches[0].pageX), {passive:true});
      track.addEventListener('touchend', onUp);
      track.addEventListener('touchcancel', onUp);

      // Elastic resistance hint at edges
      function edgeHint(){
        const max = track.scrollWidth - track.clientWidth;
        if(max <= 0) return;
        const x = track.scrollLeft;
        if(x <= 0 || x >= max-1){
          track.animate([{transform:'translateX(0px)'},{transform:'translateX(6px)'},{transform:'translateX(0px)'}],
            {duration: 420, easing:'cubic-bezier(.2,.85,.2,1)'}
          );
        }
      }
      track.addEventListener('scrollend', edgeHint);
      // Fallback: approximate end with timeout
      let st;
      track.addEventListener('scroll', () => {
        clearTimeout(st);
        st = setTimeout(edgeHint, 110);
      }, {passive:true});
